// Merge configuration from all trigger types
const input = $input.first().json;

// Handle webhook body, form data, or defaults
const config = {
  // Metadata
  projectName: input.projectName || input['Project Name'] || 'Transcript Analysis',
  dashboardTitle: input.dashboardTitle || input['Dashboard Title'] || 'Transcript Analysis Dashboard',
  participants: (input.participants || input['Participants (comma-separated)'] || '').split(',').map(p => p.trim()).filter(Boolean),
  tags: (input.tags || input['Tags (comma-separated)'] || '').split(',').map(t => t.trim()).filter(Boolean),
  dateRange: input.dateRange || input['Date Range'] || '',

  // Styling
  primaryColor: input.primaryColor || input['Primary Brand Color'] || '#2563eb',
  secondaryColor: input.secondaryColor || input['Secondary Brand Color'] || '#7c3aed',
  accentColor: input.accentColor || '#f59e0b',
  logoUrl: input.logoUrl || input['Logo URL (optional)'] || '',
  customCss: input.customCss || input['Custom CSS (optional)'] || '',
  stylingInstructions: input.stylingInstructions || input['Custom Styling Instructions'] || '',

  // Processing options
  outputFormat: input.outputFormat || input['Output Format'] || 'Both HTML and JSON',
  processingMode: input.processingMode || input['Processing Mode'] || 'Full (reprocess all files)',
  sectionsToInclude: input.sectionsToInclude || input['Sections to Include'] || 'all',

  // Notifications
  notificationWebhook: input.notificationWebhook || input['Notification Webhook URL (optional)'] || '',

  // Internal tracking
  runId: `run-${Date.now()}`,
  startedAt: new Date().toISOString()
};

// Determine output flags
config.generateHtml = config.outputFormat.includes('HTML') || config.outputFormat.includes('Both');
config.generateJson = config.outputFormat.includes('JSON') || config.outputFormat.includes('Both');
config.incrementalMode = config.processingMode.includes('Incremental');

// Parse sections
if (config.sectionsToInclude === 'all') {
  config.sections = ['questions', 'topics', 'tools', 'sessions', 'graph', 'summary', 'heatmap'];
} else {
  config.sections = config.sectionsToInclude.split(',').map(s => s.trim().toLowerCase());
}

return [{ json: { config } }];

// Initialize status tracking file
const config = $input.first().json.config;

const status = {
  runId: config.runId,
  status: 'initializing',
  phase: 'file_discovery',
  startedAt: config.startedAt,
  config: {
    projectName: config.projectName,
    outputFormat: config.outputFormat,
    processingMode: config.processingMode
  },
  progress: {
    filesDiscovered: 0,
    filesProcessed: 0,
    filesSkipped: 0,
    filesFailed: 0,
    currentFile: null
  },
  errors: [],
  lastUpdated: new Date().toISOString()
};

return [{ json: { config, status } }];

const config = $('Merge Configuration').first().json.config;
const response = $json.result;

// Parse file list from Claude response
let files = [];
try {
  const match = response.match(/\[[\s\S]*\]/);
  if (match) {
    files = JSON.parse(match[0]);
  }
} catch (e) {
  throw new Error('Failed to parse file list: ' + e.message);
}

// Load previous processing state for incremental mode
let previousState = {};
try {
  // In a real implementation, this would read from a state file
  // For now, we'll check if summaries exist
  previousState = {}; // Would be loaded from /transcripts/.processing-state.json
} catch (e) {
  previousState = {};
}

// Filter files based on processing mode
const processableFiles = files.map(file => {
  const fileHash = `${file.filename}-${file.sizeBytes}-${file.modifiedTime}`;
  const previousHash = previousState[file.filename];

  return {
    ...file,
    outputPath: `/transcripts/summaries/${file.filename.replace(/\.(vtt|srt|txt|json)$/i, '.md')}`,
    shouldProcess: !config.incrementalMode || fileHash !== previousHash,
    fileHash,
    skipReason: config.incrementalMode && fileHash === previousHash ? 'unchanged' : null
  };
});

const toProcess = processableFiles.filter(f => f.shouldProcess);
const toSkip = processableFiles.filter(f => !f.shouldProcess);

// Update status
const status = {
  phase: 'file_discovery_complete',
  progress: {
    filesDiscovered: files.length,
    filesToProcess: toProcess.length,
    filesToSkip: toSkip.length
  }
};

console.log(`Found ${files.length} files: ${toProcess.length} to process, ${toSkip.length} to skip`);

return [{
  json: {
    config,
    status,
    allFiles: processableFiles,
    filesToProcess: toProcess,
    skippedFiles: toSkip
  }
}];

