// Split files for parallel processing
const data = $('Parse & Filter Files').first().json;
const files = data.filesToProcess;

if (files.length === 0) {
  return [{ json: { ...data, noFilesToProcess: true } }];
}

return files.map((file, index) => ({
  json: {
    ...file,
    config: data.config,
    totalFiles: files.length,
    fileIndex: index + 1
  }
}));

// Aggregate results with error handling
const items = $input.all();
const config = items[0]?.json?.config || $('Parse & Filter Files').first().json.config;
const allFilesData = $('Parse & Filter Files').first().json;

const results = items.map(item => item.json);
const successful = results.filter(r => r.success);
const failed = results.filter(r => !r.success);

const status = {
  phase: 'individual_analysis_complete',
  progress: {
    filesProcessed: successful.length,
    filesFailed: failed.length,
    filesSkipped: allFilesData.skippedFiles?.length || 0
  },
  errors: failed.map(f => ({ file: f.filename, error: f.error || 'Unknown error' }))
};

return [{
  json: {
    config,
    status,
    results: {
      successful,
      failed,
      skipped: allFilesData.skippedFiles || []
    }
  }
}];

