const config = $('Merge Configuration').first().json.config;

const outputs = {
  summaries: '/transcripts/summaries/',
  combinedAnalysis: '/transcripts/combined-analysis.md',
  statusFile: '/transcripts/.status.json'
};

if (config.generateJson) {
  outputs.jsonData = '/transcripts/analysis-data.json';
}

if (config.generateHtml) {
  outputs.dashboard = '/transcripts/dashboard.html';
}

return [{ json: { config, outputs } }];

